class Solution {
public:
    vector<int> leftmostBuildingQueries(vector<int>& heights, vector<vector<int>>& queries) {
        int n = heights.size();
        int q = queries.size();
        vector<int> ans(q, -1);
        vector<vector<pair<int, int>>> pending(n);
        for (int qi = 0; qi < q; qi++) {
            int a = queries[qi][0], b = queries[qi][1];
            if (a > b) swap(a, b);
            if (a == b || heights[a] < heights[b]) ans[qi] = b;
            else pending[b].push_back({heights[a], qi});
        }
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        for (int i = 0; i < n; i++) {
            while (!pq.empty() && pq.top().first < heights[i]) {
                ans[pq.top().second] = i;
                pq.pop();
            }
            for (auto& req : pending[i]) pq.push(req);
        }
        return ans;
    }
};

class Solution {
    public int[] leftmostBuildingQueries(int[] heights, int[][] queries) {
        int n = heights.length;
        int q = queries.length;
        int[] ans = new int[q];
        Arrays.fill(ans, -1);
        List<int[]>[] pending = new ArrayList[n];
        for (int i = 0; i < n; i++) pending[i] = new ArrayList<>();
        for (int qi = 0; qi < q; qi++) {
            int a = queries[qi][0], b = queries[qi][1];
            if (a > b) { int tmp = a; a = b; b = tmp; }
            if (a == b || heights[a] < heights[b]) ans[qi] = b;
            else pending[b].add(new int[]{heights[a], qi});
        }
        PriorityQueue<int[]> pq = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
        for (int i = 0; i < n; i++) {
            while (!pq.isEmpty() && pq.peek()[0] < heights[i]) {
                int[] top = pq.poll();
                ans[top[1]] = i;
            }
            for (int[] req : pending[i]) pq.offer(req);
        }
        return ans;
    }
}

/**
 * @param {number[]} heights
 * @param {number[][]} queries
 * @return {number[]}
 */
var leftmostBuildingQueries = function(heights, queries) {
    const n = heights.length;
    const q = queries.length;
    const ans = new Int32Array(q).fill(-1);
    const pending = Array.from({ length: n }, () => []);
    for (let qi = 0; qi < q; qi++) {
        let [a, b] = queries[qi];
        if (a > b) [a, b] = [b, a];
        if (a === b || heights[a] < heights[b]) ans[qi] = b;
        else pending[b].push([heights[a], qi]);
    }
    const heap = [];
    function push(item) {
        heap.push(item);
        let idx = heap.length - 1;
        while (idx > 0) {
            const p = (idx - 1) >> 1;
            if (heap[p][0] > heap[idx][0]) {
                [heap[p], heap[idx]] = [heap[idx], heap[p]];
                idx = p;
            } else break;
        }
    }
    function pop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let idx = 0;
            while ((idx << 1) + 1 < heap.length) {
                let left = (idx << 1) + 1, right = left + 1, best = left;
                if (right < heap.length && heap[right][0] < heap[left][0]) best = right;
                if (heap[best][0] < heap[idx][0]) {
                    [heap[best], heap[idx]] = [heap[idx], heap[best]];
                    idx = best;
                } else break;
            }
        }
        return top;
    }
    for (let i = 0; i < n; i++) {
        while (heap.length > 0 && heap[0][0] < heights[i]) {
            const [_, qi] = pop();
            ans[qi] = i;
        }
        for (const req of pending[i]) push(req);
    }
    return Array.from(ans);
};
